                /**
                 * Obsluha změny hodnoty u filtru s jednou hodnotou (multi pole se chová jako single a je možné myší odvybrat hodnotu)
                 *
                 * @param {string} name prvek
                 * @param {any} ev ev z události change
                 * @param {any} changeObj changeObj z události change
                 * @param {string} [name] název položky v DTO (jmenuje-li se jinak než name)
                 */
                filterAnoNeChange(name, ev, changeObj, readerName) {
                    if (changeObj?.value?.length != null && changeObj?.value?.length > 1) {
                        // zvolená může být pouze jedna hodnota (je to simulace ne-multi režimu, která ale umožňovu myší odvybrat všechny hodnoty)
                        let newSingleVal = {};
                        changeObj?.value.forEach((v) => {
                            if (v[readerName ?? name] != null) {
                                (this["currfilter_" + name] ?? []).forEach((n) => {
                                    if (n[readerName ?? name] != null && n[readerName ?? name] !== v[readerName ?? name]) {
                                        newSingleVal[readerName ?? name] = v[readerName ?? name];
                                    }
                                });
                            }
                        });
                        if (newSingleVal[readerName ?? name] != null) {
                            $(ev.target).gfield("setValue", null);
                            $(ev.target).gfield("setValue", newSingleVal);
                        }
                    }
                    this["currfilter_" + name] = $(ev.target).gfield("getValue");
                }
                /**
                 * Úprava typ_upo ve filtru podle povolených typů pohybů
                 *
                 * @param {any} filters filtry
                 * @param {number[]} typ_upo povolené typy pohybů
                 * @returns {any} filtry s upraveným typ_upo
                 */
                modifyFilterTypUpo(filters, typ_upo) {
                    let modifFilters = filters ?? {};
                    modifFilters.typ_upo = (modifFilters.typ_upo && modifFilters.typ_upo.length > 0) ? modifFilters.typ_upo.filter((val) => (typ_upo.findIndex((t) => (t === val)) >= 0)) : typ_upo;
                    return modifFilters;
                }
                /**
                 * Rozšíření filtrů o filtry podle typu seznamu
                 *
                 * @param {any} filters aktuální filtry
                 * @returns {any} upravené filtry
                 */
                modifyFilters(filters) {
                    // TODO: nepoužít TypUpoPodleTypuSeznamu, tam by měly být všechny povolené kategorie?
                    if (this.TypSeznamu === Gordic.Fuc.Globals.Enums.TypSezPoh.UcetniPohyby) {
                        // všechny nerezervační pohyby
                        filters = this.modifyFilterTypUpo(filters, [Gordic.Fuc.Globals.Enums.TypUpo.UcetniAutomaticky, Gordic.Fuc.Globals.Enums.TypUpo.UcetniStorno, Gordic.Fuc.Globals.Enums.TypUpo.UcetniPoloautomaticky, Gordic.Fuc.Globals.Enums.TypUpo.UcetniRucni, Gordic.Fuc.Globals.Enums.TypUpo.Neucetni]);
                    }
                    else if (this.TypSeznamu === Gordic.Fuc.Globals.Enums.TypSezPoh.RezervacniPohyby) {
                        // jen rezervační pohyby
                        filters = this.modifyFilterTypUpo(filters, [Gordic.Fuc.Globals.Enums.TypUpo.Rezervacni]);
                    }
                    else if (this.TypSeznamu === Gordic.Fuc.Globals.Enums.TypSezPoh.Uctovani) {
                        // jen nezaúčtované nestornované účetní pohyby aktuálního roku a aktuální kategorie
                        // TODO: tyhle položky nedávat do filtru
                        filters = this.modifyFilterTypUpo(filters, [Gordic.Fuc.Globals.Enums.TypUpo.UcetniAutomaticky, Gordic.Fuc.Globals.Enums.TypUpo.UcetniStorno, Gordic.Fuc.Globals.Enums.TypUpo.UcetniPoloautomaticky, Gordic.Fuc.Globals.Enums.TypUpo.UcetniRucni]);
                        $.extend(filters, {
                            s_upo: [Gordic.Fuc.Globals.Enums.SUpo.Nezauctovany],
                            s_sto: [Gordic.Fuc.Globals.Enums.SSto.Nestornovano],
                            rok: this.Rok,
                            uct_poh: this.UctPoh,
                            bez_soupisky: true,
                            huf_neuctovane: true
                        });
                    }
                    return filters;
                }
                //#endregion
                //#region Menu
